"""Record actual check levels. Text comparisons are explicitly not proofs."""
from build_records import OUT,table
import json
items=json.loads((OUT/'items.json').read_text());claims=json.loads((OUT/'claims.json').read_text())
who='GPT-6 Astra Pro; effort=not exposed; run=SA02 cotes90_91'
